/*
 * A048752  Mean integral divisors associated with A048751.
 * https://oeis.org/A048752
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = A007955(A048751(n))/A000005(A048751(n)) Here A048751(n)
 *            is the n-th integer m (starting at m = 6) for which product of
 *            divisors of m divided by the number of divisors is an integer.
 *            The value of a(n) is that integer quotient. The sequence is
 *            generated by enumerating m in increasing order a...
 * Range:     u8 n <= 4, u16 n <= 8, u32 n <= 20, u64 n <= 85, u128 n <= 255,
 *            big any n
 * Helpers:   big_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  The implementation uses only integer arithmetic and the helper
    big_pow from utils.  No floating point or <math.h> is used.  */

#include <stddef.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/big_pow.h"

/* ---------- prime sieve used only for trial division ---------- */

/* list of known primes  */
static uint64_t *prime_list = NULL;
static size_t prime_count = 0;
static size_t prime_capacity = 0;
static idx_t prime_limit = 1;          /* largest number already tested */

/* Append a new prime to the list.  */
static void add_prime(uint64_t p)
{
    if (prime_count == prime_capacity) {
        size_t new_cap = prime_capacity == 0 ? 16 : prime_capacity * 2;
        uint64_t *tmp = (uint64_t *)realloc(prime_list, new_cap * sizeof(uint64_t));
        if (!tmp) abort();
        prime_list = tmp;
        prime_capacity = new_cap;
    }
    prime_list[prime_count++] = p;
}

/* Ensure primes are known up to 'limit'.  */
static void ensure_primes_upto(idx_t limit)
{
    if (limit <= prime_limit) return;
    for (idx_t n = prime_limit + 1; n <= limit; ++n) {
        if (n < 2) continue;
        bool is_prime = true;
        idx_t r = 1;
        while ((r + 1) * (r + 1) <= n) ++r;      /* simple isqrt */
        for (size_t i = 0; i < prime_count && prime_list[i] <= r; ++i) {
            if (n % prime_list[i] == 0) { is_prime = false; break; }
        }
        if (is_prime) add_prime(n);
    }
    prime_limit = limit;
}

/* Factorise n using primes in prime_list; the caller supplies buffers
    large enough to hold the result.  */
static void factor_u64(idx_t n, uint64_t *primes, int *exps, size_t *cnt)
{
    size_t k = 0;
    idx_t tmp = n;
    for (size_t i = 0; i < prime_count && prime_list[i] * prime_list[i] <= tmp; ++i) {
        if (tmp % prime_list[i] == 0) {
            int e = 0;
            while (tmp % prime_list[i] == 0) {
                tmp /= prime_list[i];
                ++e;
            }
            primes[k] = prime_list[i];
            exps[k] = e;
            ++k;
        }
    }
    if (tmp > 1) {
        primes[k] = tmp;
        exps[k] = 1;
        ++k;
    }
    *cnt = k;
}

/* ---------- compute a single term ---------- */

static bool compute_a_value(idx_t m, seq_t *out)
{
    /* factor m */
    uint64_t pm[32];
    int em[32];
    size_t cnt_m;
    factor_u64(m, pm, em, &cnt_m);

    /* compute tau(m) = product (e_i + 1) */
    idx_t tau = 1;
    for (size_t i = 0; i < cnt_m; ++i)
        tau *= (idx_t)(em[i] + 1);

    /* factor tau to get its prime powers */
    uint64_t pt[32];
    int e_tau[32];
    size_t cnt_tau;
    factor_u64(tau, pt, e_tau, &cnt_tau);

    /* check divisibility condition */
    for (size_t i = 0; i < cnt_tau; ++i) {
        uint64_t q = pt[i];
        int vq_tau = e_tau[i];
        /* find exponent of q in m */
        int vq_m = 0;
        for (size_t j = 0; j < cnt_m; ++j) {
            if (pm[j] == q) { vq_m = em[j]; break; }
        }
        if (vq_m == 0) return false;   /* q ∤ m  */
        unsigned __int128 exp_num = (unsigned __int128)vq_m * tau;
        exp_num /= 2;                   /* exp_num = (e_i * tau)/2  */
        if (exp_num < (unsigned __int128)vq_tau) return false;
    }

    /* compute the quotient:  m^(tau/2) / tau  */
    seq_t res = 1;
    for (size_t i = 0; i < cnt_m; ++i) {
        unsigned __int128 exp128 = (unsigned __int128)em[i] * tau;
        exp128 /= 2;                              /* exponent for this prime */
        seq_t exp_seq = (seq_t)exp128;
        seq_t pow = big_pow((seq_t)pm[i], exp_seq);
        res = res * pow;
    }
    res = res / (seq_t)tau;
    *out = res;
    return true;
}

/* ---------- cache and main accessor ---------- */

static seq_t *cache = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;
static idx_t next_m = 6;          /* start from the first m that gives a term */

static void grow_cache(size_t need)
{
    if (cache_cap >= need) return;
    size_t new_cap = cache_cap == 0 ? 16 : cache_cap * 2;
    while (new_cap < need) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    cache = tmp;
    cache_cap = new_cap;
}

/*  Public function required by the harness  */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* out of bounds, undefined  */
    while (cache_len < (size_t)n) {
        /* ensure we have enough primes to factor next_m and its tau  */
        idx_t limit = next_m > 1 ? next_m : 2;
        /* sqrt(next_m) + 1 approximated by simple loop  */
        idx_t sqrt_lim = 1;
        while ((sqrt_lim + 1) * (sqrt_lim + 1) <= next_m) ++sqrt_lim;
        if (sqrt_lim > limit) limit = sqrt_lim;
        ensure_primes_upto(limit);

        seq_t val;
        if (compute_a_value(next_m, &val) && val != (seq_t)1) {
            grow_cache(cache_len + 1);
            cache[cache_len++] = val;
        }
        ++next_m;
    }
    return cache[n - 1];
}
